export function hasPermission(
  ctx: { readonly permissions: readonly Permission[] } | null,
  resource: string,
  action: string,
): boolean {
  return (
    ctx?.permissions.some(
      (p) =>
        p === `${resource}:${action}` ||
        p === `${resource}:*` ||
        p === `*:${action}` ||
        p === "*:*",
    ) ?? false
  );

